package com.yara.ai.games
class ConnectFourGame{val rows=6;val cols=7;val board=Array(rows){IntArray(cols)};var over=false;fun drop(col:Int,p:Int):Boolean{if(over||col !in 0 until cols)return false;for(r in rows-1 downTo 0)if(board[r][col]==0){board[r][col]=p;over=won(r,col,p)||board.all{it.all{v->v!=0}};return true};return false};fun ai():Int{val options=(0 until cols).filter{board[0][it]==0};val c=options.maxByOrNull{score(it)}?:-1;if(c>=0)drop(c,2);return c};private fun score(c:Int):Int{var s=0;for(r in rows-1 downTo 0)if(board[r][c]==0){board[r][c]=2;s=if(won(r,c,2))100 else 1;board[r][c]=0;break};return s};private fun won(r:Int,c:Int,p:Int):Boolean{fun count(dr:Int,dc:Int):Int{var n=0;var y=r;var x=c;while(y in 0 until rows&&x in 0 until cols&&board[y][x]==p){n++;y+=dr;x+=dc};return n};return listOf(1 to 0,0 to 1,1 to 1,1 to -1).any{count(it.first,it.second)+count(-it.first,-it.second)-1>=4}}
}
